package cn.dreamingfish.launcher.loaders;
import cn.dreamingfish.launcher.*;
import cn.dreamingfish.launcher.downloads.*;
import cn.dreamingfish.launcher.launch.*;
import cn.dreamingfish.launcher.storage.LauncherStorage;
import cn.dreamingfish.launcher.vanilla.InstallationReceipt;
import java.io.*;
import java.nio.file.Path;
import java.util.*;

public final class LoaderLaunchSupport {
 private final LauncherStorage storage;
 public LoaderLaunchSupport(Path root){storage=new LauncherStorage(root);}
 public LaunchPlan apply(LaunchPlan base,CancellationToken token)throws IOException{
  var identity=base.installation().component();if(identity==null)return base;
  Path relative=Path.of("instances",base.instanceId(),"installations",base.installationId());if(!base.installationDirectory().equals(storage.root().resolve(relative)))throw new LaunchFailure("INSTALLATION_INVALID","核心安装目录不匹配");
  var records=new HashMap<String,InstallationReceipt.FileEntry>();for(var record:base.installation().files())records.put(record.path(),record);byte[] bytes=read(relative,records,identity.profilePath(),2*1024*1024,token);boolean quilt=identity.kind()==GameInstance.LoaderKind.QUILT;var quiltProfile=quilt?QuiltProfile.parse(bytes,base.instance().gameVersion(),identity.version()):null;var forge=quilt?null:ForgeClientProfile.parse(bytes,identity,base.instance().gameVersion());var libraries=quilt?quiltProfile.libraries():forge.libraries();var classpath=new LinkedHashSet<Path>();var replacements=new HashSet<String>();
  for(var lib:libraries){String path="libraries/"+lib.path();var record=records.get(path);if(record==null)throw new LaunchFailure("INSTALLATION_INVALID","核心依赖缺少固定收据");verify(relative.resolve(path),record,token);if(lib.size()!=null&&lib.size()!=record.size())throw new LaunchFailure("FILE_CHANGED","核心依赖长度不符");if(lib.digest()!=null)verifySource(relative.resolve(path),lib.digest(),token);classpath.add(storage.root().resolve(relative).resolve(path));replacements.add(libraryKey(Path.of(path)));}
  if(identity.kind()==GameInstance.LoaderKind.NEOFORGE)for(var record:records.values())if(record.path().startsWith("libraries/net/minecraft/client/")&&record.path().endsWith("-extra.jar")){verify(relative.resolve(record.path()),record,token);classpath.add(base.installationDirectory().resolve(record.path()));}
  for(Path path:base.classpath()){if(!quilt&&path.equals(base.installationDirectory().resolve("versions/client.jar")))continue;Path local=base.installationDirectory().relativize(path);if(!replacements.contains(libraryKey(local)))classpath.add(path);}
  String separator=base.installation().platform().osName().equals("windows")?";":":";if(classpath.stream().anyMatch(p->p.toString().contains(separator)))throw new LaunchFailure("INVALID_ARGUMENT","核心数据目录含类路径分隔符");var jvm=new ArrayList<>(base.jvmTokens());var args=base.jvmArguments();int cp=args.indexOf("-cp");if(Collections.frequency(args,"-cp")!=1||cp+1>=args.size())throw new LaunchFailure("UNSUPPORTED_LAUNCH_FORMAT","原版类路径参数不支持");String joined=String.join(separator,classpath.stream().map(Path::toString).toList());jvm.set(cp+1,LaunchArguments.literal(joined));var game=new ArrayList<>(base.gameTokens());if(forge!=null){var fixed=Map.of("library_directory",base.installationDirectory().resolve("libraries").toString(),"classpath_separator",separator,"version_name","client");for(String template:forge.jvm()){if(template.startsWith("${library_directory}/"))for(String path:template.split("\\$\\{classpath_separator}",-1)){String local="libraries/"+path.substring(21);var record=records.get(local);if(record==null)throw new LaunchFailure("INSTALLATION_INVALID","核心模块缺少收据");verify(relative.resolve(local),record,token);}jvm.add(LaunchArguments.compile(template,fixed));}for(String value:forge.game())game.add(LaunchArguments.literal(value));}
  var i=base.instance();return new LaunchPlan(new GameInstance(i.id(),i.name(),i.gameVersion(),identity.kind(),i.directory()),base.installation(),base.javaRuntime(),base.identity(),base.settingsRevision(),base.installationDirectory(),new ArrayList<>(classpath),jvm,quilt?quiltProfile.mainClass():forge.mainClass(),game,base.assetIndexId(),base.virtualAssets(),base.mapToResources(),base.natives());
 }
 private static String libraryKey(Path path){if(!path.startsWith("libraries")||path.getNameCount()<5)return path.toString();Path parent=path.getParent();String artifact=parent.getParent().getFileName().toString(),version=parent.getFileName().toString(),file=path.getFileName().toString(),prefix=artifact+"-"+version;return parent.getParent()+"/"+(file.startsWith(prefix)?file.substring(prefix.length()):file);}
 private byte[] read(Path root,Map<String,InstallationReceipt.FileEntry> entries,String path,int max,CancellationToken token)throws IOException{var entry=entries.get(path);if(entry==null||entry.size()>max)throw new LaunchFailure("INSTALLATION_INVALID","核心描述缺失或过大");verify(root.resolve(path),entry,token);byte[] bytes=storage.read(root.resolve(path),max);if(!LoaderPlan.hash(bytes).equals(entry.sha256()))throw new LaunchFailure("FILE_CHANGED","核心描述已变化");return bytes;}
 private void verify(Path path,InstallationReceipt.FileEntry entry,CancellationToken token)throws IOException{if(!storage.exists(path)||storage.size(path)!=entry.size())throw new LaunchFailure("FILE_CHANGED","核心依赖缺失或长度变化");verifySource(path,new FileDigest(FileDigest.Algorithm.SHA256,entry.sha256()),token);}
 private void verifySource(Path path,FileDigest expected,CancellationToken token)throws IOException{var digest=expected.newDigest();try(var in=storage.openRead(path)){byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1){token.check();digest.update(block,0,n);}}if(!HexFormat.of().formatHex(digest.digest()).equals(expected.hex()))throw new LaunchFailure("FILE_CHANGED","核心依赖摘要变化");}
}
